type Node =
  | { kind: 'file'; bytes: number }
  | { kind: 'dir'; name: string; children: Node[] };

function size(node: Node): number {
  switch (node.kind) {
    case 'file': return node.bytes;
    case 'dir': return node.children.reduce((sum, child) => sum + size(child), 0);
    default: { const unreachable: never = node; return unreachable; }
  }
}

