type Node =
  | { kind: 'file'; bytes: number }
  | { kind: 'dir'; name: string; children: Node[] };

function size(node: Node): number {
  switch (node.kind) {
    case 'file': return node.bytes;
    case 'dir': return node.children.reduce((sum, child) => sum + size(child), 0);
    default: { const unreachable: never = node; return unreachable; }
  }
}

abstract class Component { abstract size(): number; }

class FileNode extends Component {
  constructor(private bytes: number) { super(); }
  size() { return this.bytes; }
}

class DirNode extends Component {
  private children: Component[] = [];
  add(child: Component) { this.children.push(child); }
  size() { return this.children.reduce((sum, child) => sum + child.size(), 0); }
}
